changes.text:
{
  "protocol": "temple/surface-process-module/1",
  "queries": {
    "publication.build": [
      {
        "call": "identity.runtime.build"
      },
      {
        "assert": [
          "eq",
          [
            "count",
            [
              "subjects",
              "isa",
              "Place"
            ]
          ],
          40
        ],
        "message": "Publication must retain all forty places."
      },
      {
        "call": "microsites.build"
      },
      {
        "call": "frontdoors.claimipedia"
      },
      {
        "call": "frontdoors.worldwright"
      },
      {
        "call": "atlas.build"
      },
      {
        "call": "frontdoors.capabilities"
      },
      {
        "call": "encounter.build"
      },
      {
        "call": "hierarchy.build"
      },
      {
        "each": [
          "subjects",
          "isa",
          "PublicationAsset"
        ],
        "as": "asset",
        "steps": [
          {
            "port": "text.matches",
            "args": {
              "value": [
                "one",
                "$asset",
                "path"
              ],
              "pattern": "\\.(?:m?js)$|/regenerate\\.cjs$"
            },
            "into": "legacyExecutable"
          },
          {
            "when": "$legacyExecutable",
            "then": [
              {
                "port": "file.remove",
                "args": {
                  "path": [
                    "one",
                    "$asset",
                    "path"
                  ]
                },
                "into": "_"
              },
              {
                "when": [
                  "optional",
                  "$asset",
                  "legacyAlias"
                ],
                "then": [
                  {
                    "port": "file.remove",
                    "args": {
                      "path": [
                        "one",
                        "$asset",
                        "legacyAlias"
                      ]
                    },
                    "into": "_"
                  }
                ]
              }
            ]
          },
          {
            "when": [
              "not",
              "$legacyExecutable"
            ],
            "then": [
              {
                "port": "file.copy",
                "args": {
                  "path": [
                    "one",
                    "$asset",
                    "path"
                  ]
                },
                "into": "_"
              },
              {
                "when": [
                  "optional",
                  "$asset",
                  "legacyAlias"
                ],
                "then": [
                  {
                    "port": "file.read",
                    "args": {
                      "path": [
                        "one",
                        "$asset",
                        "path"
                      ]
                    },
                    "into": "legacyBytes"
                  },
                  {
                    "port": "file.write",
                    "args": {
                      "path": [
                        "one",
                        "$asset",
                        "legacyAlias"
                      ],
                      "text": "$legacyBytes"
                    },
                    "into": "_"
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "call": "publication.icon"
      },
      {
        "let": "projection",
        "value": "main"
      },
      {
        "call": "publication.styles"
      },
      {
        "port": "file.write",
        "args": {
          "path": "expedition.css",
          "text": "$css"
        },
        "into": "_"
      },
      {
        "let": "projection",
        "value": "activity"
      },
      {
        "call": "publication.styles"
      },
      {
        "port": "file.write",
        "args": {
          "path": "activity.css",
          "text": "$css"
        },
        "into": "_"
      },
      {
        "let": "prefix",
        "value": ""
      },
      {
        "let": "pageTitle",
        "value": [
          "concat",
          "Aaron Alderman — ",
          [
            "one",
            "site",
            "headline"
          ]
        ]
      },
      {
        "let": "description",
        "value": [
          "one",
          "site",
          "description"
        ]
      },
      {
        "let": "canonical",
        "value": [
          "one",
          "site",
          "origin"
        ]
      },
      {
        "let": "light",
        "value": "home"
      },
      {
        "call": "publication.home"
      },
      {
        "let": "body",
        "value": "$result"
      },
      {
        "call": "publication.document"
      },
      {
        "port": "file.write",
        "args": {
          "path": "index.html",
          "text": [
            "concat",
            "<!doctype html>\n",
            "$result"
          ]
        },
        "into": "_"
      },
      {
        "each": [
          "subjects",
          "isa",
          "Place"
        ],
        "as": "place",
        "steps": [
          {
            "let": "prefix",
            "value": "../"
          },
          {
            "let": "pageTitle",
            "value": [
              "concat",
              [
                "one",
                "$place",
                "title"
              ],
              " — Aaron Alderman"
            ]
          },
          {
            "let": "description",
            "value": [
              "one",
              "$place",
              "lead"
            ]
          },
          {
            "let": "canonical",
            "value": [
              "concat",
              [
                "one",
                "site",
                "origin"
              ],
              [
                "one",
                "$place",
                "route"
              ]
            ]
          },
          {
            "let": "light",
            "value": [
              "one",
              "$place",
              "light"
            ]
          },
          {
            "call": "publication.place"
          },
          {
            "let": "body",
            "value": "$result"
          },
          {
            "call": "publication.document"
          },
          {
            "port": "file.write",
            "args": {
              "path": [
                "one",
                "$place",
                "route"
              ],
              "text": [
                "concat",
                "<!doctype html>\n",
                "$result"
              ]
            },
            "into": "_"
          }
        ]
      },
      {
        "call": "gateway.build"
      },
      {
        "port": "file.write",
        "args": {
          "path": "robots.txt",
          "text": [
            "concat",
            "User-agent: *\nAllow: /\nSitemap: ",
            [
              "one",
              "site",
              "origin"
            ],
            "sitemap.xml\n"
          ]
        },
        "into": "_"
      },
      {
        "let": "sitemap",
        "value": [
          "fold",
          [
            "subjects",
            "isa",
            "Place"
          ],
          "sitemapPlace",
          "xml",
          [
            "concat",
            [
              "concat",
              "<?xml version=\"1.0\" encoding=\"UTF-8\"?><urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\"><url><loc>",
              [
                "one",
                "site",
                "origin"
              ],
              "</loc></url>"
            ],
            "<url><loc>",
            [
              "one",
              "site",
              "origin"
            ],
            "gate.html</loc></url>"
          ],
          [
            "concat",
            "$xml",
            "<url><loc>",
            [
              "one",
              "site",
              "origin"
            ],
            [
              "one",
              "$sitemapPlace",
              "route"
            ],
            "</loc></url>"
          ]
        ]
      },
      {
        "let": "sitemap",
        "value": [
          "fold",
          [
            "subjects",
            "isa",
            "MicrositeDocument"
          ],
          "document",
          "xml",
          "$sitemap",
          [
            "concat",
            "$xml",
            "<url><loc>",
            [
              "one",
              "$document",
              "canonical"
            ],
            "</loc></url>"
          ]
        ]
      },
      {
        "let": "sitemap",
        "value": [
          "fold",
          [
            "subjects",
            "isa",
            "StandalonePage"
          ],
          "page",
          "xml",
          "$sitemap",
          [
            "concat",
            "$xml",
            "<url><loc>",
            [
              "one",
              "$page",
              "canonical"
            ],
            "</loc></url>"
          ]
        ]
      },
      {
        "port": "file.write",
        "args": {
          "path": "sitemap.xml",
          "text": [
            "concat",
            "$sitemap",
            "</urlset>"
          ]
        },
        "into": "_"
      },
      {
        "call": "readerworkshop.build"
      },
      {
        "call": "microsite.return.all"
      },
      {
        "let": "assurance",
        "value": {
          "places": [
            "count",
            [
              "subjects",
              "isa",
              "Place"
            ]
          ],
          "sourceNotes": [
            "count",
            [
              "subjects",
              "isa",
              "SourceNote"
            ]
          ],
          "policy": "Temple process algebra",
          "compatibility": "historical source oracles; algebra-owned reader and workshop",
          "budget": 20000000
        }
      }
    ],
    "publication.styles": [
      {
        "let": "cssPlan",
        "value": {
          "imports": [
            "list"
          ],
          "tokens": [
            "list"
          ],
          "rules": [
            "append",
            [
              "map",
              [
                "filter",
                [
                  "subjects",
                  "isa",
                  "StyleRule"
                ],
                "rule",
                [
                  "eq",
                  [
                    "one",
                    "$rule",
                    "projection"
                  ],
                  "$projection"
                ]
              ],
              "rule",
              {
                "id": "$rule",
                "selector": [
                  "one",
                  "$rule",
                  "selector"
                ],
                "context": [
                  "optional",
                  "$rule",
                  "context"
                ],
                "declarations": [
                  "map",
                  [
                    "objects",
                    "$rule",
                    "declaration"
                  ],
                  "decl",
                  {
                    "property": [
                      "one",
                      "$decl",
                      "property"
                    ],
                    "value": [
                      "one",
                      "$decl",
                      "value"
                    ]
                  }
                ]
              }
            ],
            [
              "if",
              [
                "eq",
                "$projection",
                "main"
              ],
              [
                "map",
                [
                  "subjects",
                  "isa",
                  "IdentityTheme"
                ],
                "theme",
                {
                  "id": [
                    "concat",
                    "questions.palette.",
                    [
                      "one",
                      "$theme",
                      "key"
                    ]
                  ],
                  "selector": [
                    "concat",
                    "html:has(body[data-question-identity=\"",
                    [
                      "one",
                      "$theme",
                      "key"
                    ],
                    "\"]),body[data-question-identity=\"",
                    [
                      "one",
                      "$theme",
                      "key"
                    ],
                    "\"]"
                  ],
                  "declarations": [
                    "map",
                    [
                      "objects",
                      "$theme",
                      "questionColour"
                    ],
                    "decl",
                    {
                      "property": [
                        "one",
                        "$decl",
                        "property"
                      ],
                      "value": [
                        "one",
                        "$decl",
                        "value"
                      ]
                    }
                  ],
                  "context": null
                }
              ],
              [
                "list"
              ]
            ]
          ]
        }
      },
      {
        "call": "css.renderPlan"
      },
      {
        "when": [
          "eq",
          "$projection",
          "main"
        ],
        "then": [
          {
            "call": "publication.motion"
          },
          {
            "let": "css",
            "value": [
              "concat",
              "$css",
              "$motionCSS"
            ]
          }
        ]
      }
    ],
    "publication.document": [
      {
        "let": "stewardshipInput",
        "value": "$result"
      },
      {
        "call": "publication.stewardship.view"
      },
      {
        "let": "stewardshipLinks",
        "value": "$result"
      },
      {
        "let": "result",
        "value": "$stewardshipInput"
      },
      {
        "let": "input",
        "value": {
          "tag": "html",
          "attrs": {
            "lang": "en"
          },
          "children": [
            "list",
            {
              "tag": "head",
              "attrs": {},
              "children": [
                "list",
                {
                  "tag": "meta",
                  "attrs": {
                    "charset": "utf-8"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "viewport",
                    "content": "width=device-width, initial-scale=1"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "theme-color",
                    "content": "#0c111b"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "title",
                  "attrs": {},
                  "children": [
                    "list",
                    "$pageTitle"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "description",
                    "content": "$description"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "link",
                  "attrs": {
                    "rel": "canonical",
                    "href": "$canonical"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:type",
                    "content": "website"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:site_name",
                    "content": "Aaron Alderman"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:title",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "title"
                      ],
                      "$pageTitle"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:description",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "description"
                      ],
                      "$description"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:url",
                    "content": "$canonical"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:image",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "image"
                      ],
                      [
                        "concat",
                        [
                          "one",
                          "site",
                          "origin"
                        ],
                        [
                          "one",
                          "site",
                          "image"
                        ]
                      ]
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:image:alt",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "alt"
                      ],
                      [
                        "one",
                        "site",
                        "imageAlt"
                      ]
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "twitter:card",
                    "content": "summary_large_image"
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "twitter:title",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "title"
                      ],
                      "$pageTitle"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "twitter:description",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "description"
                      ],
                      "$description"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "twitter:image",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "image"
                      ],
                      [
                        "concat",
                        [
                          "one",
                          "site",
                          "origin"
                        ],
                        [
                          "one",
                          "site",
                          "image"
                        ]
                      ]
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "name": "twitter:image:alt",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "alt"
                      ],
                      [
                        "one",
                        "site",
                        "imageAlt"
                      ]
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "link",
                  "attrs": {
                    "rel": "icon",
                    "type": "image/svg+xml",
                    "href": [
                      "concat",
                      "$prefix",
                      "assets/personal-mark.svg"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "link",
                  "attrs": {
                    "rel": "stylesheet",
                    "href": [
                      "concat",
                      "$prefix",
                      "expedition.css?v=",
                      [
                        "one",
                        "site",
                        "stylesheetVersion"
                      ]
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:image:width",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "width"
                      ],
                      "1672"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                {
                  "tag": "meta",
                  "attrs": {
                    "property": "og:image:height",
                    "content": [
                      "if",
                      [
                        "eq",
                        "$canonical",
                        [
                          "one",
                          "site",
                          "origin"
                        ]
                      ],
                      [
                        "one",
                        "sharing.home",
                        "height"
                      ],
                      "941"
                    ]
                  },
                  "children": [
                    "list"
                  ]
                },
                [
                  "if",
                  [
                    "eq",
                    "$canonical",
                    [
                      "one",
                      "site",
                      "origin"
                    ]
                  ],
                  {
                    "tag": "meta",
                    "attrs": {
                      "property": "og:image:secure_url",
                      "content": [
                        "one",
                        "sharing.home",
                        "image"
                      ]
                    },
                    "children": [
                      "list"
                    ]
                  },
                  null
                ],
                [
                  "if",
                  [
                    "eq",
                    "$canonical",
                    [
                      "one",
                      "site",
                      "origin"
                    ]
                  ],
                  {
                    "tag": "meta",
                    "attrs": {
                      "property": "og:image:type",
                      "content": [
                        "one",
                        "sharing.home",
                        "type"
                      ]
                    },
                    "children": [
                      "list"
                    ]
                  },
                  null
                ]
              ]
            },
            {
              "tag": "body",
              "attrs": {
                "data-light": "$light"
              },
              "children": [
                "list",
                {
                  "tag": "a",
                  "attrs": {
                    "href": "#main",
                    "class": "skip"
                  },
                  "children": [
                    "list",
                    "Skip to the story"
                  ]
                },
                {
                  "tag": "header",
                  "attrs": {
                    "class": "masthead"
                  },
                  "children": [
                    "list",
                    {
                      "tag": "a",
                      "attrs": {
                        "href": [
                          "concat",
                          "$prefix",
                          "index.html"
                        ],
                        "class": "brand",
                        "aria-label": "Aaron Alderman"
                      },
                      "children": [
                        "list",
                        {
                          "tag": "span",
                          "attrs": {},
                          "children": [
                            "list",
                            {
                              "tag": "span",
                              "attrs": {
                                "class": "monogram",
                                "aria-hidden": "true"
                              },
                              "children": [
                                "list",
                                "A"
                              ]
                            },
                            {
                              "tag": "span",
                              "attrs": {
                                "class": "brand-name"
                              },
                              "children": [
                                "list",
                                "Aaron ",
                                {
                                  "tag": "span",
                                  "attrs": {
                                    "class": "brand-surname"
                                  },
                                  "children": [
                                    "list",
                                    "Alderman"
                                  ]
                                }
                              ]
                            }
                          ]
                        }
                      ]
                    },
                    {
                      "tag": "nav",
                      "attrs": {
                        "aria-label": "Main navigation"
                      },
                      "children": [
                        "list",
                        {
                          "tag": "a",
                          "attrs": {
                            "href": [
                              "concat",
                              "$prefix",
                              "gate.html"
                            ],
                            "class": "gate-nav"
                          },
                          "children": [
                            "list",
                            "Reading paths ↗"
                          ]
                        },
                        {
                          "tag": "a",
                          "attrs": {
                            "href": [
                              "concat",
                              "$prefix",
                              "atlas.html"
                            ]
                          },
                          "children": [
                            "list",
                            "Explore the map"
                          ]
                        },
                        {
                          "tag": "a",
                          "attrs": {
                            "href": [
                              "concat",
                              "$prefix",
                              "retained/workshop/index.html"
                            ]
                          },
                          "children": [
                            "list",
                            "The workshop ↗"
                          ]
                        }
